void setup() {
  // Start the PWM library
  pwmSetup(PWM_FREQ);

  // Set the PWM duty cycle to 0
  pwmWrite(0, 0);

  // Start the PDM input
  analogInputs.begin(AC, 12);
}

void loop() {
